?>
<div class="card"><div class="card-title"><h3>Pengaturan Sistem</h3></div><form method="post"><div class="form-grid"><div class="form-group"><label>Nama Kampus</label><input class="input" name="campus_name" value="<?= e(setting($pdo,'campus_name')) ?>"></div><div class="form-group"><label>Nama Sistem</label><input class="input" name="system_name" value="<?= e(setting($pdo,'system_name')) ?>"></div><div class="form-group"><label>Gerbang Bawaan</label><select class="select" name="default_gate_id"><?php foreach($gates as $g): ?><option value="<?= $g['id_gate'] ?>" <?= setting($pdo,'default_gate_id')==$g['id_gate']?'selected':'' ?>><?= e($g['kode_gate'].' - '.$g['nama_gate']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Area Bawaan</label><select class="select" name="default_area_id"><?php foreach($areas as $a): ?><option value="<?= $a['id_area'] ?>" <?= setting($pdo,'default_area_id')==$a['id_area']?'selected':'' ?>><?= e($a['nama_area']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Durasi Servo Terbuka (ms)</label><input class="input" type="number" name="servo_open_delay" value="<?= e(setting($pdo,'servo_open_delay',3000)) ?>"></div><div class="form-group"><label>Wajib Data Kendaraan</label><select class="select" name="require_vehicle_data"><option value="0" <?= setting($pdo,'require_vehicle_data')=='0'?'selected':'' ?>>Tidak</option><option value="1" <?= setting($pdo,'require_vehicle_data')=='1'?'selected':'' ?>>Ya</option></select></div></div><div class="form-actions"><button class="btn btn-primary">Simpan Pengaturan</button></div></form></div>
